    for i in range(H):
        for j in range(W):
            if A[i][j] and (i,j) not in seen:
                stack=[(i,j)]; cells=[]
                while stack:
                    x,y=stack.pop(); c=A[x][y]
                    if (x,y) in seen or c==0: continue
                    seen.add((x,y)); cells.append((x,y))
