        G[k]=[[int(x) for x in r] for r in rows]
def comps(A,c):
    H,W=A.shape; seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if A[i][j]==c and (i,j) not in seen:
                stack=[(i,j)]; cells=[]
                while stack:
                    x,y=stack.pop()
                    if not(0<=x<H and 0<=y<W) or A[x][y]!=c or (x,y) in seen: continue
                    seen.add((x,y)); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1): stack.append((x+dx,y+dy))
                res.append(cells)
    return res
def solve(A):
