            rs=[q[0] for q in p]; cs=[q[1] for q in p]
            hh=max(rs)-min(rs); ww=max(cs)-min(cs)
            cr=(min(rs)+max(rs))//2; cc=(min(cs)+max(cs))//2
            if hh>=2 and ww>=2:          # block: both directions through center
                for i in range(H):
                    v=cov[i][cc]
                    if v is None or v==c: cov[i][cc]=c
