                    elif isinstance(v,tuple): cov[cr][j]=(v,c)
            else:                         # line: dominant axis, min coord along it
                kind=('v' if hh>=ww else 'h')
                pos=min(cs) if kind=='v' else min(rs)
                for i in range(H):
