                for j in range(W):
                    v=cov[pos][j]
                    if v is None or v==c: cov[pos][j]=c
                    elif isinstance(v,tuple): cov[pos][j]=(v,c)
    out=[[int(A[i][j]) for j in range(W)] for i in range(H)]
    for i in range(H):
        for j in range(W):
            v=cov[i][j]
            if v is not None:
                if isinstance(v,tuple): out[i][j]=0   # different colors crossing
                else: out[i][j]=v
    return out
